 not seasonally adjusted)\ncpi_1960 = 29.6\ncpi_1961 = 29.9\ncpi_1962 = 30.2\n\n# Adjust FY 1960 and FY 1961 to constant 1962 dollars\n# Formula: Adjusted = Original * (CPI_target / CPI_original)\nadjusted_1960 = debt_1960 * (cpi_1962 / cpi_1960)\nadjusted_1961 = debt_1961 * (cpi_1962 / cpi_1961)\n\nprint(f'FY 1960 debt: {debt_1960} million')\nprint(f'FY 1961 debt: {debt_1961} million')\nprint(f'FY 1962 debt: {debt_1962} million')\nprint()\nprint(f'CPI-U 1960: {cpi_1960}')\nprint(f'CPI-U 1961: {cpi_1961}')\nprint(f'CPI-U 1962: {cpi_1962}')\nprint()\nprint(f'FY 1960 adjusted to 1962 dollars: {adjusted_1960:.6f} million')\nprint(f'FY 1961 adjusted to 1962 dollars: {adjusted_1961:.6f} million')\nprint()\n\n# Calculate absolute difference\ndiff = abs(adjusted_1961 - adjusted_1960)\nprint(f'Absolute difference: {diff:.6f} million')\nprint(f'Absolute difference (rounded to thousandths): {diff:.3f}')\n\""}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
